    if n >= 100:
        return 'large'
    if n >= 10:
        return 'medium'
    return 'small'

print(size_of(150), size_of(42), size_of(3))

javascript.code:
const levels = [
  [100, 'large'],
  [10, 'medium'],
]
function sizeOf(n) {
  for (const [min, label] of levels) {
    if (n >= min) return label
  }
  return 'small'
}
console.log(sizeOf(42))

